#include <cuda_runtime.h>
#include <vector>
#define main legacy_main
#include "../colorwheel-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int s=512,h=s/2,n=3*s*s,repeats=argc>1?atoi(argv[1]):100;float truerange=1.f,range=1.04f;std::vector<uchar>expected(n),got(n);for(int y=0;y<s;y++)for(int x=0;x<s;x++){if(x==h||y==h)continue;float fx=float(x)/h*range-range,fy=float(y)/h*range-range;computeColor(fx/truerange,fy/truerange,expected.data()+(y*s+x)*3);}uchar*pix;CK(cudaMalloc(&pix,n));CK(cudaMemset(pix,0,n));color<<<dim3(32,32),dim3(16,16)>>>(pix,s,h,range,truerange);CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){CK(cudaMemset(pix,0,n));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int rep=0;rep<repeats;rep++)color<<<dim3(32,32),dim3(16,16)>>>(pix,s,h,range,truerange);CK(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeats;CK(cudaMemcpy(got.data(),pix,n,cudaMemcpyDeviceToHost));int ma=0;for(int i=0;i<n;i++)ma=std::max(ma,abs(int(got[i])-int(expected[i])));bool ok=ma<=1;all&=ok;char file[100];sprintf(file,"colorwheel_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(got.data(),1,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"colorwheel_kernel_only_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",n,ma,repeats,file,n);}CK(cudaFree(pix));puts(all?"PASS":"FAIL");return all?0:1;}
